#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <algorithm>
#include <functional>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    if (n & 1) {
        cout << -1;
        return 0;
    }

    string s;
    cin >> s;

    vector<long long> weight(n);
    vector<int> frequency(26, 0);

    for (char c : s) {
        ++frequency[c - 'a'];
    }

    for (long long &x : weight) {
        cin >> x;
    }

    for (int count : frequency) {
        if (count > n / 2) {
            cout << -1;
            return 0;
        }
    }

    long long answer = 0;
    for (long long x : weight) {
        answer += x;
    }

    vector<int> bad(26, 0);
    int totalBad = 0;

    for (int i = 0; i < n / 2; ++i) {
        int j = n - i - 1;
        if (s[i] == s[j]) {
            ++bad[s[i] - 'a'];
            ++totalBad;
            answer -= min(weight[i], weight[j]);
        }
    }

    int majorityChar = 0;
    for (int c = 1; c < 26; ++c) {
        if (bad[c] > bad[majorityChar]) {
            majorityChar = c;
        }
    }

    int extraChanges = 2 * bad[majorityChar] - totalBad;
    if (extraChanges > 0) {
        priority_queue<long long, vector<long long>, greater<long long>> costs;

        for (int i = 0; i < n / 2; ++i) {
            int j = n - i - 1;
            if (s[i] == s[j]) {
                continue;
            }

            if (s[i] - 'a' == majorityChar) {
                costs.push(weight[j]);
            } else if (s[j] - 'a' == majorityChar) {
                costs.push(weight[i]);
            } else {
                costs.push(min(weight[i], weight[j]));
            }
        }

        while (extraChanges--) {
            answer -= costs.top();
            costs.pop();
        }
    }

    cout << answer;
    return 0;
}

